        {
          "@type": "Question",
          "name": "Is pickup available in Bakersfield?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS schedules business electronics pickup throughout Bakersfield and Kern County based on equipment type, volume, loading access, and project timing. Free pickup is available for qualifying volumes. Organizations can request a practical collection plan before retiring IT equipment and can discuss scheduled pickup and documentation needs with the STS recycling team."
          }
        },
        {
          "@type": "Question",
          "name": "Do you provide audit documentation?",
          "acceptedAnswer": {
            "@type": "Answer",
            "text": "STS provides documentation covering pickup, chain of custody, and final processing. Bakersfield organizations can discuss serial-level tracking, inventory requirements, and Certificate of Destruction services during project planning. Documentation needs vary by the equipment inventory and selected service scope."
          }
